//! The script-facing handles to the borrowed context types.
//!
//! Each class is declared here; its *methods* are generated by
//! `#[utils::dynamic_scoped]` on the corresponding inherent `impl` block, so
//! adding a method to [`DrawContext`] or [`Workspace`] binds it automatically.

use pyo3::prelude::*;

use std::sync::Arc;

use std::borrow::Cow;

use crate::stubs::{StubClass, StubField, StubMethod};
use crate::{
    DrawConstraints, DrawContext, DrawResult, Node, NodeContext, NodeHandle, NodeUid, Workspace,
    messages::{Action, Request, action_for, registered_messages, request_for},
    scripting::{FromDynamic, Scoped, ScopedRef, expired_handle},
};

// ======================================================================
// DrawContext
// ======================================================================

/// A scoped handle to a live [`DrawContext`], valid only for the duration of
/// the synchronous `draw` call it was passed into.
#[pyclass(unsendable, name = "DrawContext")]
pub struct PyDrawContext {
    pub inner: Scoped<DrawContext<'static>>,
}

impl PyDrawContext {
    /// Install a handle over `ctx` for the duration of `f`.
    ///
    /// The handle is invalidated before this returns, so anything the script
    /// stashed away is inert rather than dangling.
    pub fn enter<'py, R>(
        py: Python<'py>,
        ctx: &mut DrawContext<'_>,
        f: impl FnOnce(&Bound<'py, PyDrawContext>) -> R,
    ) -> PyResult<R> {
        // Erase the borrow's lifetime; the handle outlives it only as a null pointer.
        #[allow(clippy::unnecessary_cast)] // the cast changes the lifetime, not the type
        let erased: &mut DrawContext<'static> =
            unsafe { &mut *(ctx as *mut DrawContext<'_>).cast::<DrawContext<'static>>() };
        let obj = Bound::new(
            py,
            PyDrawContext {
                inner: unsafe { Scoped::new(erased) },
            },
        )?;

        let out = f(&obj);
        obj.borrow().inner.invalidate();
        Ok(out)
    }

    /// Run `f` against the live context, or raise if the handle has expired.
    pub fn try_with<R>(&self, f: impl FnOnce(&mut DrawContext<'_>) -> R) -> PyResult<R> {
        self.inner.with(f).ok_or_else(expired_handle)
    }
}

#[pymethods]
impl PyDrawContext {
    /// This node's place in the world, as `DrawContext.node` is in Rust.
    #[getter]
    fn node(&self, py: Python<'_>) -> PyResult<Py<PyNodeContext>> {
        let (ws, id) =
            self.try_with(|ctx| (ctx.node.workspace as *const Workspace, ctx.node.id))?;
        // SAFETY: the workspace is live for this call, and the handle is
        // invalidated when the owning `PyDrawContext` expires.
        Py::new(
            py,
            PyNodeContext {
                workspace: unsafe { ScopedRef::new(&*ws) },
                id,
            },
        )
    }

    /// The constraints this node is being drawn under.
    #[getter]
    fn constraints(&self) -> PyResult<DrawConstraints> {
        self.try_with(|ctx| ctx.constraints)
    }

    /// Whether this handle still refers to a live context.
    #[getter]
    fn live(&self) -> bool {
        self.inner.is_live()
    }

    /**
        Draw `node` under `constraints`, reporting what it took.

        The counterpart of `DrawContext::draw_node`, which takes `&dyn Node` and
        so cannot be bound directly. The only thing it adds is accepting either
        form of child: a `NodeUid` handle draws the node the workspace holds
        (drawing it as a *value* would wrap the handle object itself as a script
        node), and anything else is coerced to a node. Positioning is in the
        constraints, exactly as a Rust layout writes it.
    */
    fn draw_node(
        &self,
        node: Bound<'_, PyAny>,
        constraints: DrawConstraints,
    ) -> PyResult<DrawResult> {
        let child = Child::of(&node)?;
        self.try_with(|ctx| match &child {
            Child::Held(id) => ctx
                .draw_workspace_node(*id, constraints)
                .unwrap_or(DrawResult::Complete { region: None }),
            Child::Value(arc) => ctx.draw_node(&**arc, constraints),
        })
    }

    /**
        Draw `node` over everything else, ignoring this node's bounds.

        The counterpart of `DrawContext::overlay_node`. Clip rectangles are
        intersected down the draw tree, so this is the only way for a script
        node to paint outside the box it was given — a preview that hangs off
        its node, a drag ghost, a popup.
    */
    fn overlay_node(
        &self,
        node: Bound<'_, PyAny>,
        constraints: DrawConstraints,
    ) -> PyResult<DrawResult> {
        let child = Child::of(&node)?;
        self.try_with(|ctx| match &child {
            Child::Held(id) => ctx
                .overlay_workspace_node(*id, constraints)
                .unwrap_or(DrawResult::Complete { region: None }),
            Child::Value(arc) => ctx.overlay_node(&**arc, constraints),
        })
    }
}

/// The two forms a script may pass where a node is expected.
enum Child {
    /// A handle to a node the workspace already holds. Drawing it as a value
    /// would wrap the handle object itself, so it is drawn by id instead.
    Held(NodeUid),
    /// Anything else, coerced into a node.
    Value(Arc<dyn Node>),
}

impl Child {
    fn of(node: &Bound<'_, PyAny>) -> PyResult<Self> {
        match node.extract::<NodeHandle>() {
            Ok(handle) => Ok(Self::Held(handle.0)),
            Err(_) => Ok(Self::Value(<Arc<dyn Node> as FromDynamic>::from_dynamic(
                node,
            )?)),
        }
    }
}

