// ======================================================================
// Workspace
// ======================================================================

/// A scoped handle to the live [`Workspace`], for queries and mutations a
/// script issues while it runs.
#[pyclass(unsendable, name = "Workspace")]
pub struct PyWorkspace(pub ScopedRef<Workspace>);

impl PyWorkspace {
    /// Install a handle over `ws` for the duration of `f`, invalidating it
    /// before returning.
    pub fn enter<'py, R>(
        py: Python<'py>,
        ws: &Workspace,
        f: impl FnOnce(&Bound<'py, PyWorkspace>) -> R,
    ) -> PyResult<R> {
        // SAFETY: the handle is invalidated below, before `ws`'s borrow ends.
        let obj = Bound::new(py, PyWorkspace(unsafe { ScopedRef::new(ws) }))?;
        let out = f(&obj);
        obj.borrow().0.invalidate();
        Ok(out)
    }

    /// Run `f` against the live workspace, or raise if the handle has expired.
    pub fn try_with<R>(&self, f: impl FnOnce(&Workspace) -> R) -> PyResult<R> {
        self.0.with(f).ok_or_else(expired_handle)
    }
}

#[pymethods]
impl PyWorkspace {
    /// Whether this handle still refers to a live workspace.
    #[getter]
    fn live(&self) -> bool {
        self.0.is_live()
    }

    /**
        Send `request` to `dest` and return its response.

        `Workspace::send_request` is generic over both the target node and the
        response type, so it cannot be bound directly. Instead every
        `defhandlers!` message is a bound class that registers itself, and the
        instance is matched back to its Rust type here — so every request in the
        codebase is reachable without a per-message binding.

        ```python
        text = ctx.workspace.send_request(node, dex.GetText())
        ```
    */
    fn send_request(
        &self,
        py: Python<'_>,
        dest: NodeHandle,
        request: Bound<'_, PyAny>,
    ) -> PyResult<Py<PyAny>> {
        let ws = self
            .0
            .with(|ws| ws as *const Workspace)
            .ok_or_else(expired_handle)?;
        // SAFETY: the pointer is live for this call; `with` just proved it.
        send_request_py(unsafe { &*ws }, dest.0, &request, py)
    }

    /// Queue `action` against `dest`.
    #[pyo3(signature = (dest, action, description=None))]
    fn submit_action(
        &self,
        dest: NodeHandle,
        action: Bound<'_, PyAny>,
        description: Option<String>,
    ) -> PyResult<()> {
        let entry = action_for(&action).ok_or_else(|| not_a_message(&action, false))?;
        let body = (entry.build)(&action)?;

        let queued = Action {
            dest: dest.0,
            description: description
                .map(Cow::Owned)
                .unwrap_or(Cow::Borrowed(entry.name)),
            body,
        };
        self.try_with(|ws| ws.submit_action_dyn(queued))
    }

    /// The names of every request and action a script may send, for discovery.
    #[staticmethod]
    fn message_names() -> (Vec<&'static str>, Vec<&'static str>) {
        registered_messages()
    }
}

/// Route `request` to `dest` in `ws` and hand the response back to Python.
pub(crate) fn send_request_py(
    ws: &Workspace,
    dest: NodeUid,
    request: &Bound<'_, PyAny>,
    py: Python<'_>,
) -> PyResult<Py<PyAny>> {
    let entry = request_for(request).ok_or_else(|| not_a_message(request, true))?;
    let body = (entry.build)(request)?;

    match ws.send_request_dyn(Request { dest, body }) {
        Some(any) => (entry.respond)(any, py),
        // The node did not answer; indistinguishable from a `None` answer.
        None => Ok(py.None()),
    }
}

/// The error a script sees when it passes something that is not a message.
pub(crate) fn not_a_message(obj: &Bound<'_, PyAny>, is_request: bool) -> PyErr {
    let (requests, actions) = registered_messages();
    let (kind, mut known) = if is_request {
        ("request", requests)
    } else {
        ("action", actions)
    };
    known.sort_unstable();
    let got = obj
        .get_type()
        .name()
        .map(|n| n.to_string())
        .unwrap_or_else(|_| "<unknown>".to_owned());
    pyo3::exceptions::PyTypeError::new_err(format!(
        "expected a {kind} message, got `{got}`; known {kind}s: {}",
        known.join(", ")
    ))
}

