// ======================================================================
// NodeContext
// ======================================================================

/// A scoped handle to a [`NodeContext`]: what a script-defined node's
/// `handle_action` / `request` handlers receive.
#[pyclass(unsendable, name = "NodeContext")]
pub struct PyNodeContext {
    pub(crate) workspace: ScopedRef<Workspace>,
    pub(crate) id: NodeUid,
}

impl PyNodeContext {
    /// Install a handle over `ctx` for the duration of `f`.
    pub fn enter<'py, R>(
        py: Python<'py>,
        ctx: NodeContext<'_>,
        f: impl FnOnce(&Bound<'py, PyNodeContext>) -> R,
    ) -> PyResult<R> {
        let obj = Bound::new(
            py,
            PyNodeContext {
                // SAFETY: invalidated below, before `ctx`'s borrow ends.
                workspace: unsafe { ScopedRef::new(ctx.workspace) },
                id: ctx.id,
            },
        )?;
        let out = f(&obj);
        obj.borrow().workspace.invalidate();
        Ok(out)
    }
}

#[pymethods]
impl PyNodeContext {
    /// This node's own id.
    #[getter]
    fn id(&self) -> NodeHandle {
        NodeHandle(self.id)
    }

    /// A handle to the workspace, scoped to this same call.
    #[getter]
    fn workspace(&self, py: Python<'_>) -> PyResult<Py<PyWorkspace>> {
        let ws = self
            .workspace
            .with(|ws| ws as *const Workspace)
            .ok_or_else(expired_handle)?;
        // SAFETY: live for this call; the handle expires with this context.
        Py::new(py, PyWorkspace(unsafe { ScopedRef::new(&*ws) }))
    }

    /// Whether this handle still refers to a live context.
    #[getter]
    fn live(&self) -> bool {
        self.workspace.is_live()
    }
}

